CREATE TABLE linkA_ipk(aa1 INTEGER PRIMARY KEY,aa2); INSERT INTO linkA_ipk(aa1,aa2) SELECT aa1, aa2 FROM linkA; CREATE TABLE linkB_ipk(bb1 INTEGER PRIMARY KEY,bb2); INSERT INTO linkB_ipk(bb1,bb2) SELECT bb1, bb2 FROM linkB; CREATE TABLE linkC_ipk(cc1 INTEGER PRIMARY KEY,cc2); INSERT INTO linkC_ipk(cc1,cc2) SELECT cc1, cc2 FROM linkC; CREATE TABLE linkD_ipk(dd1 INTEGER PRIMARY KEY,dd2); INSERT INTO linkD_ipk(dd1,dd2) SELECT dd1, dd2 FROM linkD; CREATE TABLE result AS WITH RECURSIVE closure(x) AS (VALUES(1) UNION ALL SELECT aa2 FROM linkA_ipk JOIN closure ON x=aa1 UNION ALL SELECT bb2 FROM linkB_ipk JOIN closure ON x=bb1 UNION ALL SELECT cc2 FROM linkC_ipk JOIN closure ON x=cc1 UNION ALL SELECT dd2 FROM linkD_ipk JOIN closure ON x=dd1) SELECT x FROM closure ORDER BY +x;